"""The per-family settings files: regenerated byte for byte by the maker from the 1B files and pins_78b.json; in the
1B schema (the 1B check_settings accepts each on its 1B name); every per-family value is the family's; every null pin is
listed in family_78b.waits with its event; the index and the wrapper's literal pin agree; the 1B scripts and settings
are byte-identical to the wrapper's and the maker's pins."""

from __future__ import annotations

import json
from pathlib import Path

import pytest

from experiments.safety_selection.common import sha256_bytes, sha256_file
from scripts.scale78b import make_scorer_settings_78b as mk
from scripts.scale78b import scorers_78b as sw
from scripts.stage1 import s1common as s1

REPO = Path(__file__).resolve().parents[4]
FAMILIES = mk.FAMILIES
PINS, PINS_SHA = mk.load_pins()


def committed(name: str) -> bytes:
    return (mk.SETTINGS_DIR / name).read_bytes()


def doc_of(script: str, family: str) -> dict:
    return json.loads(committed(mk.file_name(script, family)))


def test_the_committed_files_equal_their_regeneration():
    files = mk.derive_all(PINS)
    files[mk.INDEX_NAME] = mk.index_bytes(files, PINS_SHA)
    assert len(files) == 2 * len(mk.ORDER) + 1
    for name, data in files.items():
        assert committed(name) == data, name


def test_the_index_and_the_wrappers_literal_pin_agree():
    index = json.loads(committed(mk.INDEX_NAME))
    assert sha256_file(mk.SETTINGS_DIR / mk.INDEX_NAME) == sw.PINS_FILE_SHA256
    assert index["pins_78b_sha256"] == PINS_SHA
    for name, digest in index["files"].items():
        assert sha256_bytes(committed(name)) == digest, name
    assert set(index["files"]) == {mk.file_name(s, f) for s in mk.ORDER for f in FAMILIES}
    sw.load_pins_index()                                                  # the wrapper's own loader accepts it


@pytest.mark.parametrize("script", mk.ORDER)
@pytest.mark.parametrize("family", FAMILIES)
def test_the_1b_check_settings_accepts_each_file_on_its_1b_name(script, family):
    doc = doc_of(script, family)
    base = json.loads((mk.STAGE1_SETTINGS / f"{script}.json").read_bytes())
    assert doc["kind"] == base["kind"] == "stage1 settings" and doc["name"] == base["name"] == script
    assert doc["engine_x"] == base["engine_x"] and doc["label_entries"] == base["label_entries"]
    assert doc["owner"] == base["owner"] and doc["family_78b"]["owner_78b"] == mk.OWNER_78B
    s1.check_settings(doc, script)                                        # the frozen 1B check, unchanged
    fam = doc["family_78b"]
    assert fam["family"] == family and fam["derived_from"]["sha256"] == mk.BASE_SHA256[script]
    assert fam["manifest_sha256"] == PINS["families"][family]["manifest_sha256"]
    assert set(doc) - set(base) <= {"family_78b", "doses", "pool_pins_file_78b", "requirement_78b",
                                    "expected_evaluation_forms_note_78b", "use_78b"}, sorted(set(doc) - set(base))


@pytest.mark.parametrize("script", mk.ORDER)
@pytest.mark.parametrize("family", FAMILIES)
def test_every_null_is_listed_in_waits_and_every_wait_is_null(script, family):
    doc = doc_of(script, family)
    waits = doc["family_78b"]["waits"]
    for dotted, entry in waits.items():
        assert mk.get_path(doc, dotted) is None, dotted
        assert entry["event"] and isinstance(entry["needed_by"], list)

    def nulls(node, prefix=""):
        if isinstance(node, dict):
            for key, value in node.items():
                yield from nulls(value, f"{prefix}.{key}" if prefix else key)
        elif node is None:
            yield prefix
    found = {p for p in nulls(doc) if not p.startswith("family_78b")}
    base_nulls = {p for p in nulls(json.loads((mk.STAGE1_SETTINGS / f"{script}.json").read_bytes()))}
    new_nulls = found - base_nulls                                       # nulls the 1B file does not have
    assert new_nulls <= set(waits), sorted(new_nulls - set(waits))
    if script == "representation_pools":                                  # the 1B file's own nulls, kept, documented
        assert {"pools.decoy.sha256", "pools.plant.sha256"} <= found


@pytest.mark.parametrize("family", FAMILIES)
def test_the_per_family_values(family):
    fam = PINS["families"][family]
    other = [f for f in FAMILIES if f != family][0]
    main_sha = fam["main_recipe"]["config_sha256"]
    u = doc_of("make_untuned_answers", family)
    assert u["pins"]["rec_recipe_sha256"] == main_sha and u["pins"]["recipe_s_sha256"] == main_sha
    assert u["lists"]["s4"]["keep"] == 192 and u["lists"]["s4"]["size"] == 512 and u["chunk"] == 32
    assert u["doses"]["sizes"] == [48, 96, 192] and u["doses"]["sizing"]["candidates_for_top_dose_at_1b_rate"] == 216
    assert u["doses"]["sizing"]["chunks_for_top_dose_at_1b_rate"] == 7
    r = doc_of("representation_pass", family)
    assert r["pins"]["prepared_manifest_sha256"] == fam["manifest_sha256"] != PINS["families"][other]["manifest_sha256"]
    assert r["pins"]["model"] == fam["model_pin"] and r["pins"]["recipe_sha256"] is None and r["pins"]["anchor_bank_sha256"] is None
    l1 = doc_of("score_l1_larf", family)
    assert l1["pins"]["rec_recipe_sha256"] == main_sha and l1["pins"]["anchor_bank_sha256"] is None
    assert l1["pins"]["representation_pass_settings_sha256"] == sha256_bytes(committed(mk.file_name("representation_pass", family)))
    assert l1["scan"]["first_block"] == 10 and l1["scan"]["modules"] == {fam["l1_scan_modules"]["model_type"]: fam["l1_scan_modules"]["modules"]}
    c = doc_of("score_classifier", family)
    assert c["pins"]["model"] == fam["model_pin"] and c["pins"]["recipe_sha256"] is None
    s3 = doc_of("score_s3_datarx", family)
    assert s3["pins"]["representation_pass_settings_sha256"] == l1["pins"]["representation_pass_settings_sha256"]
    w = doc_of("write_score_edit", family)
    unit = w["a1"]["attributes_unit"]
    assert unit["complete_sha256"] is None and unit["retrain_complete_sha256"] is None and unit["code_sha256"] is None
    assert unit["seed"] == 1101 and w["prepared"]["manifest_sha256"] == fam["manifest_sha256"]
    assert w["prepared"]["rows"] == 4800 and w["prepared"]["units"] == 8 and w["prepared"]["rows_per_unit"] == 600
    a = doc_of("write_add_edit", family)
    assert {k: v["rows"] for k, v in a["lists"].items()} == {"s1": 48, "s3": 48, "s4": 48, "s4_96": 96, "s4_192": 192, "s4_top": None}
    assert a["prepared_manifest_sha256"] == fam["manifest_sha256"] and a["recipe_sha256"] == main_sha
    p = doc_of("build_s_pool", family)
    assert p["inputs"]["rec_recipe_sha256"] == main_sha and p["inputs"]["prepared_manifest_sha256"] == fam["manifest_sha256"]
    pools = doc_of("representation_pools", family)
    assert all(e["sha256"] is None for e in pools["pools"].values())


def test_the_two_families_differ_only_where_they_should():
    for script in mk.ORDER:
        a, b = doc_of(script, "olmo2-7b"), doc_of(script, "llama31-8b")
        diff = {p for p in paths(a) | paths(b) if get(a, p) != get(b, p)}
        allowed = ("family_78b.", "pins.", "prepared", "inputs.rec_", "inputs.prepared_manifest_sha256",
                   "a1.attributes_unit.source", "a1.edit_name", "recipe_sha256", "pool_pins_file_78b",
                   "scan.modules")                                       # PP12: each family's own entry (track M)
        assert all(p.startswith(allowed) for p in diff), (script, sorted(diff))
        assert diff or script == "representation_pools", script           # every other file carries a per-family value


def paths(node, prefix=""):
    if isinstance(node, dict):
        out = set()
        for k, v in node.items():
            out |= paths(v, f"{prefix}.{k}" if prefix else k)
        return out
    return {prefix}


def get(doc, dotted):
    node = doc
    for key in dotted.split("."):
        if not isinstance(node, dict) or key not in node:
            return KeyError
        node = node[key]
    return node


def test_the_1b_scripts_and_settings_are_byte_identical_to_the_pins():
    for rel, digest in sw.STAGE1_CODE.items():
        assert sha256_file(REPO / rel) == digest, rel
    for script, digest in mk.BASE_SHA256.items():
        assert sha256_file(mk.STAGE1_SETTINGS / f"{script}.json") == digest, script
    kit = (REPO / "runkit" / "stage1-olmo" / "stage1_rules.py").read_text(encoding="utf-8")
    for rel in ("scripts/stage1/make_untuned_answers.py", "scripts/stage1/representation_pass.py",
                "scripts/stage1/score_l1_larf.py", "scripts/stage1/score_classifier.py", "scripts/stage1/s1common.py"):
        assert f'"{rel}": "{sw.STAGE1_CODE[rel]}"' in kit, rel                # the stage-1 kit pins the same bytes


def test_the_maker_refuses_a_changed_1b_file_and_bad_pins(tmp_path, monkeypatch):
    monkeypatch.setitem(mk.BASE_SHA256, "score_s3_datarx", "0" * 64)
    with pytest.raises(mk.MakerError, match="hashes to"):
        mk.load_base("score_s3_datarx")
    bad = json.loads(mk.PINS_PATH.read_bytes())
    bad["families"]["olmo2-7b"]["anchor_bank_sha256"] = "not-a-hash"
    p = tmp_path / "pins_78b.json"
    p.write_bytes(json.dumps(bad).encode())
    with pytest.raises(mk.MakerError, match="neither null nor a SHA-256"):
        mk.load_pins(p)
    bad = json.loads(mk.PINS_PATH.read_bytes())
    bad["shared"]["s4_doses"] = [48, 192, 96]
    p.write_bytes(json.dumps(bad).encode())
    with pytest.raises(mk.MakerError, match="nested sizes"):
        mk.load_pins(p)


def test_check_mode_passes_on_the_committed_files_and_fails_on_a_change(tmp_path, capsys):
    assert mk.main(["--check"]) == 0
    import shutil

    shutil.copytree(mk.SETTINGS_DIR, tmp_path / "s")
    (tmp_path / "s" / mk.file_name("score_s3_datarx", "olmo2-7b")).write_bytes(b"{}\n")
    assert mk.main(["--check", "--settings-dir", str(tmp_path / "s")]) == 1
    assert "differ: score_s3_datarx__olmo2-7b.json" in capsys.readouterr().out
